-- Privacy operations and administrator-managed compliance requirements.
-- No personal data is seeded. Retention periods require legal approval.
CREATE TABLE KU_PRIVACY_REQUESTS (REQUEST_ID VARCHAR2(36) PRIMARY KEY, USER_ID VARCHAR2(64) NOT NULL, REQUEST_TYPE VARCHAR2(30) NOT NULL, DETAILS VARCHAR2(2000), STATUS VARCHAR2(20) DEFAULT 'OPEN' NOT NULL, REQUESTED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, DUE_AT TIMESTAMP, RESOLVED_AT TIMESTAMP, RESOLUTION_NOTE VARCHAR2(2000), CONSTRAINT CK_KU_PRIVACY_REQ_TYPE CHECK (REQUEST_TYPE IN ('ACCESS','CORRECTION','ERASURE','WITHDRAW_CONSENT','GRIEVANCE')), CONSTRAINT CK_KU_PRIVACY_REQ_STATUS CHECK (STATUS IN ('OPEN','IN_REVIEW','COMPLETED','REJECTED')));
CREATE INDEX IDX_KU_PRIV_REQ_USER ON KU_PRIVACY_REQUESTS (USER_ID, REQUESTED_AT DESC);
CREATE INDEX IDX_KU_PRIV_REQ_STATUS ON KU_PRIVACY_REQUESTS (STATUS, REQUESTED_AT);
CREATE TABLE KU_PRIVACY_NOTICE_ACKS (ACK_ID VARCHAR2(36) PRIMARY KEY, USER_ID VARCHAR2(64) NOT NULL, NOTICE_VERSION VARCHAR2(40) NOT NULL, LANGUAGE_CODE VARCHAR2(8) DEFAULT 'en' NOT NULL, ACKNOWLEDGED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT UQ_KU_PRIV_NOTICE_ACK UNIQUE (USER_ID, NOTICE_VERSION, LANGUAGE_CODE));
CREATE TABLE KU_COMPLIANCE_CONFIG (CONFIG_KEY VARCHAR2(100) PRIMARY KEY, CONFIG_VALUE VARCHAR2(2000) NOT NULL, UPDATED_BY VARCHAR2(64), UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE KU_SECURITY_AUDIT_EVENTS (EVENT_ID VARCHAR2(36) PRIMARY KEY, ACTOR_USER_ID VARCHAR2(64), EVENT_TYPE VARCHAR2(80) NOT NULL, SUBJECT_TYPE VARCHAR2(50), SUBJECT_ID VARCHAR2(100), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, METADATA VARCHAR2(2000));
CREATE INDEX IDX_KU_SEC_AUDIT_TIME ON KU_SECURITY_AUDIT_EVENTS (CREATED_AT);
